/* Service worker: saves the site on the device so it works offline, and updates it one file at a time.
 *
 * pwa-files.js (generated by tools/build_pwa.py) lists every file with a content hash.
 *   - Core files (pages, styles, scripts, data, fonts) are saved when the worker installs. A file whose hash has not
 *     changed is kept, so an update downloads only what changed.
 *   - Diagram images are saved as they are viewed, or all at once from the "Offline use" panel.
 *   - Everything else (PDFs, downloads, other sites) goes straight to the network.
 * Saved files are looked up by path, ignoring ?query and #hash, so theory/skull.html?q=atlas works offline.
 */
"use strict";

importScripts("pwa-files.js");

var P = self.PWA;
var CORE = "cca-core";
var IMG = "cca-img";
var BASE = new URL("./", self.registration.scope).href; // the site root, ending in "/"

function keyFor(rel, hash) {
  return BASE + encodeURI(rel) + "?h=" + hash;
}

/* "https://host/repo/theory/skull.html?q=x" -> "theory/skull.html" (null when it is not part of this site) */
function relOf(href) {
  var u = new URL(href);
  var path = u.origin + u.pathname;
  if (path.indexOf(BASE) !== 0) return null;
  var rel = decodeURIComponent(path.slice(BASE.length));
  if (rel === "" || rel.slice(-1) === "/") rel += "index.html";
  return rel;
}

function offlinePage() {
  return caches.open(CORE).then(function (c) {
    return c.match(keyFor("offline.html", P.core["offline.html"])).then(function (r) {
      return r || new Response("This page is not saved on this device.", { status: 503, headers: { "Content-Type": "text/plain" } });
    });
  });
}

/* Fetch what is missing from the core cache, a few files at a time. Any failure stops the install, so the
 * previous version stays in use until the whole new set can be saved. */
function precache() {
  return caches.open(CORE).then(function (cache) {
    var queue = Object.keys(P.core);
    function worker() {
      var rel = queue.shift();
      if (!rel) return Promise.resolve();
      var key = keyFor(rel, P.core[rel]);
      return cache
        .match(key)
        .then(function (hit) {
          if (hit) return null;
          return fetch(BASE + encodeURI(rel), { cache: "reload" }).then(function (res) {
            if (!res.ok) throw new Error(rel + " returned " + res.status);
            return cache.put(key, res);
          });
        })
        .then(worker);
    }
    return Promise.all([worker(), worker(), worker(), worker(), worker(), worker()]).then(function () {
      return fetch(BASE + "pwa-files.js", { cache: "reload" }).then(function (res) {
        if (!res.ok) throw new Error("pwa-files.js returned " + res.status);
        return cache.put(BASE + "pwa-files.js", res);
      });
    });
  });
}

/* Remove saved files that the current list no longer contains (changed or deleted files). */
function tidy() {
  var keepCore = {};
  Object.keys(P.core).forEach(function (r) {
    keepCore[keyFor(r, P.core[r])] = true;
  });
  keepCore[BASE + "pwa-files.js"] = true; // the last copy of the file list, so the offline panel works without a connection
  var keepImg = {};
  Object.keys(P.img).forEach(function (r) {
    keepImg[keyFor(r, P.img[r])] = true;
  });
  function prune(name, keep) {
    return caches.open(name).then(function (cache) {
      return cache.keys().then(function (reqs) {
        return Promise.all(
          reqs.map(function (rq) {
            return keep[rq.url] ? null : cache.delete(rq);
          })
        );
      });
    });
  }
  return caches
    .keys()
    .then(function (names) {
      return Promise.all(
        names.map(function (n) {
          return n === CORE || n === IMG ? null : caches.delete(n);
        })
      );
    })
    .then(function () {
      return Promise.all([prune(CORE, keepCore), prune(IMG, keepImg)]);
    });
}

self.addEventListener("install", function (e) {
  e.waitUntil(
    precache().then(function () {
      return self.skipWaiting();
    })
  );
});

self.addEventListener("activate", function (e) {
  e.waitUntil(
    tidy().then(function () {
      return self.clients.claim();
    })
  );
});

function fromCore(rel, req) {
  return caches
    .open(CORE)
    .then(function (c) {
      return c.match(keyFor(rel, P.core[rel]));
    })
    .then(function (hit) {
      return hit || fetch(req);
    })
    .catch(function () {
      return req.mode === "navigate" ? offlinePage() : Response.error();
    });
}

function fromImages(rel, req) {
  var key = keyFor(rel, P.img[rel]);
  return caches.open(IMG).then(function (cache) {
    return cache.match(key).then(function (hit) {
      if (hit) return hit;
      return fetch(req).then(function (res) {
        if (res.ok && res.status === 200) cache.put(key, res.clone());
        return res;
      });
    });
  });
}

self.addEventListener("fetch", function (e) {
  var req = e.request;
  if (req.method !== "GET" || req.headers.has("range")) return;
  var rel = relOf(req.url);
  if (rel === null || rel === "sw.js") return;
  if (rel === "pwa-files.js") {
    /* network first, so the list is always current; the last copy is kept for when there is no connection */
    e.respondWith(
      fetch(req)
        .then(function (res) {
          if (res.ok) {
            var copy = res.clone();
            caches.open(CORE).then(function (c) {
              c.put(BASE + "pwa-files.js", copy);
            });
          }
          return res;
        })
        .catch(function () {
          return caches.open(CORE).then(function (c) {
            return c.match(BASE + "pwa-files.js").then(function (r) {
              return r || Response.error();
            });
          });
        })
    );
    return;
  }
  if (Object.prototype.hasOwnProperty.call(P.core, rel)) {
    e.respondWith(fromCore(rel, req));
  } else if (Object.prototype.hasOwnProperty.call(P.img, rel)) {
    e.respondWith(fromImages(rel, req));
  } else if (req.mode === "navigate") {
    e.respondWith(
      fetch(req).catch(function () {
        return offlinePage();
      })
    );
  }
});
